/* Stage 2 (real Mednafen save-state BAT/VRAM/CRAM)
 *
 * Generated by tools/pack_stage_state.py:
 *   stage2_state_maps.bin : 4 screens x 32x24 plane A entries
 *   stage2_state_tiles.bin: 46 distinct 8x8 tiles converted to MD format
 *   stage2_state_pal.bin  : 4 MD palettes (PCE palettes 15,0,14,5)
 *   player_spr.bin        : engine player test art
 */

.section .rodata
#include <macros.s>

GLABEL res_stage2_state_tiles
.incbin "../res/gfx/stage2_state_tiles.bin"
.align 2

GLABEL res_stage2_state_pal
.byte 0
.byte 63
.incbin "../res/gfx/stage2_state_pal.bin"
.align 2

GLABEL res_stage2_state_maps
.incbin "../res/gfx/stage2_state_maps.bin"
.align 2

GLABEL res_player_spr
.incbin "../res/gfx/player_spr.bin"
.align 2
